select (select md5(coalesce(string_agg(concat_ws('|', m.annonce, m.numero, coalesce(k.valeur_app, '-'), coalesce(k.origine, '-'), coalesce(k.ecrit_par, '-'), coalesce(r.mandat_charge_honoraires_app, '-')), ';' order by m.annonce, m.numero), '')) from (values ('63490', '18999'), ('59164', '18127'), ('59339', '18143'), ('54734', '18053'), ('17597', '18973'), ('62336', '18648'), ('62766', '18773'), ('11695', '17296'), ('59637', '18286'), ('62934', '18950'), ('63299', '18942'), ('39684', '17987'), ('61893', '18996')) m(annonce, numero) left join public.app_mandat_champ_app k on k.hektor_annonce_id = m.annonce and k.numero_mandat = m.numero and k.champ = 'charge_commission' left join public.app_mandat_register_current r on r.hektor_annonce_id::text = m.annonce and r.numero_mandat::text = m.numero) as empreinte;
